// The IdP's signing certificate, generated by keygen into shared/keys/.
//
// Phase 3 publishes the certificate (public half) in metadata. Phase 4 adds
// the private key (idp.key) for signing Assertions.

import { X509Certificate } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { config } from "../config.ts";

export interface SigningCertificate {
  /** The PEM file as-is ("-----BEGIN CERTIFICATE----- ..."). */
  pem: string;
  /**
   * The certificate as it goes inside <ds:X509Certificate>: the base64 DER
   * body of the PEM, without the BEGIN/END lines or line breaks
   * (XML Signature §4.4.4 X509Data).
   */
  base64Der: string;
  /** SHA-256 fingerprint, for humans comparing certs across systems. */
  fingerprint256: string;
  validTo: string;
}

export function loadSigningCertificate(): SigningCertificate {
  const pem = readFileSync(path.join(config.keysDir, "idp.crt"), "utf8");
  // Parsing it with Node's X509Certificate proves it's a real certificate and
  // not, say, an empty or truncated file — fail at startup, not mid-login.
  const cert = new X509Certificate(pem);
  return {
    pem,
    base64Der: cert.raw.toString("base64"),
    fingerprint256: cert.fingerprint256,
    validTo: cert.validTo,
  };
}
